-- 补充Roblox 命名空间
-- 生成的代码,泛型会报错,此处用 System.Object代替所有Roblox命名空间下的泛型类型

local System = _G.System
local rTable = {base = { System.Attribute } }
setmetatable(rTable,{
  __index = function(self,name)
    local c = System.defInf(name)
    self[name] = c
    getmetatable(c).__call = function()
      return {}
    end
    return c
  end
})
_G.Roblox = rTable
_G.Roblox.GlobalEnums = rTable

return {}